CREATE TABLE cages (id VARCHAR(100) PRIMARY KEY, tenant_id UUID NOT NULL, code VARCHAR(100) NOT NULL, name VARCHAR(300), kind VARCHAR(50) NOT NULL, capacity INTEGER NOT NULL, active BOOLEAN NOT NULL, notes TEXT, created_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(100) NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(tenant_id, code));
CREATE TABLE hospitalizations (id VARCHAR(100) PRIMARY KEY, tenant_id UUID NOT NULL, patient_id UUID NOT NULL, status VARCHAR(30) NOT NULL, planned_at TIMESTAMPTZ, admitted_at TIMESTAMPTZ, admitted_by VARCHAR(100), discharged_at TIMESTAMPTZ, discharged_by VARCHAR(100), cancel_reason TEXT, reason TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(100) NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE cage_assignments (id VARCHAR(100) PRIMARY KEY, tenant_id UUID NOT NULL, hospitalization_id VARCHAR(100) NOT NULL REFERENCES hospitalizations(id), cage_id VARCHAR(100) NOT NULL REFERENCES cages(id), "from" TIMESTAMPTZ NOT NULL, "to" TIMESTAMPTZ, ended_by VARCHAR(100), notes TEXT, created_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(100) NOT NULL);
CREATE INDEX hospitalizations_tenant_patient_status_idx ON hospitalizations(tenant_id, patient_id, status); CREATE INDEX cage_assignments_tenant_cage_interval_idx ON cage_assignments(tenant_id, cage_id, "from", "to");
ALTER TABLE cages ENABLE ROW LEVEL SECURITY; ALTER TABLE hospitalizations ENABLE ROW LEVEL SECURITY; ALTER TABLE cage_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE cages FORCE ROW LEVEL SECURITY; ALTER TABLE hospitalizations FORCE ROW LEVEL SECURITY; ALTER TABLE cage_assignments FORCE ROW LEVEL SECURITY;
CREATE POLICY cages_tenant ON cages USING (tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK (tenant_id=current_setting('app.tenant_id',true)::uuid); CREATE POLICY hospitalizations_tenant ON hospitalizations USING (tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK (tenant_id=current_setting('app.tenant_id',true)::uuid); CREATE POLICY cage_assignments_tenant ON cage_assignments USING (tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK (tenant_id=current_setting('app.tenant_id',true)::uuid);
